/**
 * CONTORNO DEL MUNDO, país a país — generado, no escrito a mano.
 *
 * Origen: Natural Earth 1:110m (admin 0, fronteras de país), que es DOMINIO PÚBLICO, redistribuido
 * como TopoJSON en el paquete `world-atlas` de Mike Bostock (licencia ISC). Aquí no se usa ninguna
 * de las dos cosas en tiempo de ejecución: el TopoJSON se decodificó una vez y se guardó ya
 * proyectado, que es lo único que necesita un SVG.
 *
 * LA PROYECCIÓN ES EQIRECTANGULAR (plate carrée), la más simple que existe: la longitud es la x y la
 * latitud es la y, sin más. Se eligió justo por eso — con ella, poner un punto en el mapa es una
 * regla de tres sobre sus coordenadas reales (`proyectar()` más abajo) y no hay que arrastrar una
 * librería de proyecciones al navegador. Deforma mucho cerca de los polos, lo que aquí da igual: el
 * vino más al sur de la carta está en el Cabo Occidental y el más al norte en el Ródano.
 *
 *     x = (longitud + 180) × 2000 / 360
 *     y = (90 − latitud)  × 1000 / 180
 *
 * RUSIA Y FIYI LLEGAN A LOS DOS LADOS DEL MAPA, y eso en una proyección plana es un problema: dos
 * puntos seguidos de su contorno pasan de +179° a −179°, que aquí son 2.000 px de salto, y dibujado
 * tal cual sale una banda cruzando el mundo entero. Sus contornos se parten en el meridiano 180 al
 * generarlos, así que cada trozo se dibuja por su lado, con sus extremos llevados hasta el borde del lienzo para que la recta que cierra cada trozo corra por el borde y no por encima del país.
 *
 * La Antártida se queda fuera a propósito (no hay viñedo y se come un cuarto del lienzo), igual que
 * las islas de menos de ~1,2 unidades² de área, que a este tamaño son motas de polvo.
 *
 * Pesa unos 110 kB de texto (≈40 kB comprimido). Es el precio de que el mapa sea un SVG de verdad
 * —escala sin pixelarse, se colorea con CSS y se puede navegar con el teclado— en vez de una imagen.
 */

/** Lienzo del mapa, en unidades de la proyección de arriba. */
export const MUNDO_VIEWBOX = { width: 2000, height: 1000 } as const;

/** Longitud y latitud reales → punto del lienzo. */
export function proyectar(lon: number, lat: number): { x: number; y: number } {
  return { x: ((lon + 180) * MUNDO_VIEWBOX.width) / 360, y: ((90 - lat) * MUNDO_VIEWBOX.height) / 180 };
}

export interface PaisDelMundo {
  /** Código ISO 3166-1 numérico, tal cual lo trae Natural Earth. */
  id: string;
  /** Nombre en inglés de Natural Earth. NO se pinta: solo sirve para cruzarlo con `NACIONES`. */
  name: string;
  /** El contorno, ya proyectado. */
  d: string;
}

